package vn.rtr.aeris.native97;
import android.os.SystemClock;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.function.BooleanSupplier;
/** APK owns all GCS payload writes. Fixed AP endpoint; raw TX injection unavailable to WebView. */
public final class PayloadNative97{
 private final File root;private final BooleanSupplier foreground,flightOpen;private PayloadCore97 core;private Socket socket;private RawJournal95 raw;private boolean open=false,used=false;private String run=null;private long started=0;private int rx=0,tx=0;private String lastState="";
 public PayloadNative97(File base,BooleanSupplier f,BooleanSupplier flight)throws IOException{root=new File(base.getCanonicalFile(),"payload97");foreground=f;flightOpen=flight;if(java.nio.file.Files.isSymbolicLink(root.toPath()))throw new IOException("PAYLOAD_ROOT_SYMLINK");if(!root.exists()&&!root.mkdir())throw new IOException("PAYLOAD_ROOT_CREATE");}
 public synchronized boolean isOpen(){return open;}
 private void append(String kind,String data)throws Exception{raw.append(kind,data.getBytes(StandardCharsets.UTF_8));}
 private JSONObject state()throws Exception{JSONObject j=core==null?new JSONObject().put("phase","CLOSED").put("stations",new JSONArray()).put("payloads",new JSONArray()).put("transactions",new JSONArray()).put("generation","").put("revision",0).put("authorityRestorable",false):new JSONObject(Data97.json(core.snapshot(SystemClock.elapsedRealtime())));j.put("ok",true).put("open",open).put("run",run==null?JSONObject.NULL:run).put("rxBytes",rx).put("txBytes",tx);return j;}
 private long integer(JSONObject q,String k)throws Exception{Object v=q.get(k);if(!(v instanceof Number))throw new IOException("INTEGER_TYPE");double d=((Number)v).doubleValue();long n=((Number)v).longValue();if(!Double.isFinite(d)||d!=n||n<0||n>9007199254740991L)throw new IOException("INTEGER_RANGE");return n;}
 private float number(JSONObject q,String k)throws Exception{Object v=q.get(k);if(!(v instanceof Number)||!Double.isFinite(((Number)v).doubleValue()))throw new IOException("NUMBER_TYPE");float n=((Number)v).floatValue();if(!Float.isFinite(n))throw new IOException("NUMBER_RANGE");return n;}
 private void exact(JSONObject q,String...keys)throws Exception{Set<String>a=new HashSet<>();Iterator<String>it=q.keys();while(it.hasNext())a.add(it.next());if(!a.equals(new HashSet<>(Arrays.asList(keys))))throw new IOException("PAYLOAD_REQUEST_SHAPE");}
 public synchronized String request(String action,String body)throws Exception{JSONObject q=new JSONObject(body);try{
  if(action.equals("state")){exact(q);return state().toString();}
  if(action.equals("history")){exact(q);JSONArray runs=new JSONArray();File[]dirs=root.listFiles();if(dirs==null||dirs.length>32)throw new IOException("PAYLOAD_HISTORY_BOUND");for(File d:dirs){if(java.nio.file.Files.isSymbolicLink(d.toPath())||!d.isDirectory())throw new IOException("PAYLOAD_HISTORY_PATH");File f=new File(d,"raw.jsonl");runs.put(new JSONObject().put("run",d.getName()).put("bytes",f.length()).put("sha256",DraftStore.hash(RawArchive96.read(f.toPath(),RawArchive96.RAW))).put("authorityRestorable",false));}return new JSONObject().put("ok",true).put("runs",runs).toString();}
  if(action.equals("close")){exact(q,"acknowledge");if(!q.getBoolean("acknowledge"))throw new IOException("EXPLICIT_CLOSE_REQUIRED");close("EXPLICIT_CLOSE");return state().toString();}
  if(action.equals("open")){exact(q,"syntheticAcknowledged");if(!q.getBoolean("syntheticAcknowledged")||used||!foreground.getAsBoolean()||flightOpen.getAsBoolean())throw new IOException("EXPLICIT_NEW_ACTIVITY_SYNTHETIC_IDLE_REQUIRED");if(!android.os.Build.HARDWARE.equals("ranchu")||!android.os.Build.MODEL.toLowerCase(java.util.Locale.ROOT).contains("sdk"))throw new IOException("OWNED_EMULATOR_ONLY");File[]old=root.listFiles();if(old==null||old.length>=32||root.getUsableSpace()<DraftStore.RESERVE+40L*1024*1024)throw new IOException("PAYLOAD_QUOTA_NO_DELETE");used=true;run=UUID.randomUUID().toString();File dir=new File(root,run);if(!dir.mkdir())throw new IOException("PAYLOAD_RUN_EXISTS");raw=new RawJournal95(new File(dir,"raw.jsonl"),SystemClock::elapsedRealtime);core=new PayloadCore97();append("META",new JSONObject().put("format","aeris-native97-payload-meta").put("version",1).put("sourceId",BuildInfo90.SOURCE_ID).put("run",run).put("endpoint","10.0.2.2:5917").put("origin","SYNTHETIC_PAYLOAD_VIA_ACTUAL_AP_ROUTER").put("remoteAuthentication",false).put("actualImages",0).put("authorityRestorable",false).toString());socket=new Socket();socket.connect(new InetSocketAddress("10.0.2.2",5917),3000);socket.setTcpNoDelay(true);socket.setSoTimeout(300);open=true;started=SystemClock.elapsedRealtime();append("SOCKET_CONNECTED","{\"endpoint\":\"10.0.2.2:5917\"}");new Thread(this::reader,"native97-payload-reader").start();new Thread(this::pulse,"native97-payload-pulse").start();return state().toString();}
  if(!open||!foreground.getAsBoolean()||flightOpen.getAsBoolean())throw new IOException("PAYLOAD_CURRENT_FOREGROUND_LINK_REQUIRED");long now=SystemClock.elapsedRealtime();
  if(action.equals("join")){exact(q,"actor");append("JOIN_INTENT",q.toString());core.join(q.getString("actor"),now);}
  else if(action.equals("heartbeat")){exact(q,"sid");core.heartbeat(q.getString("sid"),now);}
  else if(action.equals("discover")){exact(q,"acknowledge");if(!q.getBoolean("acknowledge"))throw new IOException("EXPLICIT_DISCOVERY_REQUIRED");for(PayloadCore97.Tx t:core.discover(now))send(t.bytes,t.id);}
  else if(action.equals("action")){exact(q,"sid","seq","revision","generation","kind","payload","to","acknowledge");if(!q.getBoolean("acknowledge"))throw new IOException("EXPLICIT_CONSENT_REQUIRED");append("AUTHORITY_INTENT",q.toString());core.act(q.getString("sid"),integer(q,"seq"),integer(q,"revision"),q.getString("generation"),q.getString("kind"),q.getString("payload"),q.getString("to"),now);}
  else if(action.equals("command")){exact(q,"sid","seq","revision","generation","payload","operation","a","b","acknowledge");if(!q.getBoolean("acknowledge"))throw new IOException("EXPLICIT_COMMAND_CONFIRM_REQUIRED");append("COMMAND_INTENT",q.toString());PayloadCore97.Tx t=core.command(q.getString("sid"),integer(q,"seq"),integer(q,"revision"),q.getString("generation"),q.getString("payload"),q.getString("operation"),number(q,"a"),number(q,"b"),now);send(t.bytes,t.id);}
  else throw new IOException("PAYLOAD_ACTION_UNKNOWN");append("STATE",Data97.json(core.snapshot(SystemClock.elapsedRealtime())));return state().toString();
 }catch(Exception e){if(raw!=null)try{append("REJECTED",new JSONObject().put("action",action).put("error",String.valueOf(e.getMessage())).toString());}catch(Exception journalError){close("JOURNAL_FAILURE");}if(action.equals("open")||core!=null&&core.isClosed())close("CORE_REVOKED");throw e;}}
 private synchronized void send(byte[]b,String id)throws Exception{if(!open||!foreground.getAsBoolean()||flightOpen.getAsBoolean())throw new IOException("PAYLOAD_WRITE_REVOKED");core.tick(SystemClock.elapsedRealtime());append("TX_BINDING",new JSONObject().put("id",id).put("sha256",DraftStore.hash(b)).toString());raw.append("TX_INTENT",b);if(!foreground.getAsBoolean())throw new IOException("PAYLOAD_BACKGROUND_BEFORE_WRITE");Map<String,Object>approval=core.approve(id,b,SystemClock.elapsedRealtime());try{socket.getOutputStream().write(b);socket.getOutputStream().flush();raw.append("TX_WRITTEN",b);append("TX_APPROVAL",Data97.json(approval));tx+=b.length;}catch(Exception e){close("WRITE_UNKNOWN_NO_RETRY");throw e;}}
 private void pulse(){while(true){try{Thread.sleep(500);synchronized(this){if(!open)return;if(!foreground.getAsBoolean()||SystemClock.elapsedRealtime()-started>600000)throw new IOException("LIFECYCLE_OR_DEADLINE");byte[]b=core.heartbeatBytes(SystemClock.elapsedRealtime());send(b,"GCS_HEARTBEAT");}}catch(Exception e){close("PULSE_"+e.getMessage());return;}}}
 private void reader(){byte[]b=new byte[4096];while(true){try{Socket s;synchronized(this){if(!open)return;s=socket;}int n;try{n=s.getInputStream().read(b);}catch(SocketTimeoutException t){synchronized(this){if(open)core.tick(SystemClock.elapsedRealtime());}continue;}if(n<0)throw new IOException("NATIVE_EOF");if(n==0)continue;synchronized(this){if(!open)return;byte[]copy=Arrays.copyOf(b,n);raw.append("RX",copy);rx+=n;core.receive(copy,SystemClock.elapsedRealtime());String current=Data97.json(core.snapshot(SystemClock.elapsedRealtime()));if(!current.equals(lastState)){append("STATE",current);lastState=current;}}}catch(Exception e){close("RX_"+e.getMessage());return;}}}
 public synchronized void close(String reason){if(!used)return;open=false;if(core!=null)core.close(reason);if(socket!=null)try{socket.close();}catch(Exception ignored){}if(raw!=null){try{append("CLOSED",new JSONObject().put("reason",reason).put("safeAircraftState","NOT_ASSERTED").put("authorityRestorable",false).toString());raw.close();}catch(Exception ignored){}raw=null;}}
}
